package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int64
	fmt.Fscan(reader, &n)

	// f(0) = 1, f(1) = 2, f(k) = f(k-1) + f(k-2)
	// find max k such that f(k) <= n
	a := int64(1) // f(k-2)
	b := int64(2) // f(k-1)
	if n < a {
		fmt.Println(0)
		return
	}
	if n < b {
		fmt.Println(0)
		return
	}

	k := 1
	for {
		var c int64
		// check overflow
		if b > n-a { // b+a > n would overflow risk, but n up to 1e18, use safe check
			// c = a+b might exceed n or overflow int64
			c = a + b
			if c > n || c < 0 {
				break
			}
		} else {
			c = a + b
		}

		if c > n {
			break
		}
		a = b
		b = c
		k++
	}

	fmt.Println(k)
}
